head.script:
scwin.onpageload = function() {
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList2.insertRow();
    dataList2.insertRow();
    dataList2.insertRow();
};
scwin.onpageunload = function() {};
scwin.dataList1_oncelldatachange = function(info) {
    if (info.colID == "col1") {
        dataList2.setCellData(info.rowIndex, "col1", info.newValue);
    }
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-sequence', {
        sequence: '111'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-sequence', {
        sequence: '222'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Tab0_tab_tab2').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Tab0_tab_tab1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Tab0_tab_tab2').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+$p.id+'gridView2_cell_0_1').innerText == '111222'", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
